class DSU {
public:
    vector<int> parent, rank;

    DSU(int n) : parent(n), rank(n, 1) {
        for (int i = 0; i < n; i++) parent[i] = i;
    }

    int find(int node) {
        if (parent[node] != node)
            parent[node] = find(parent[node]);
        return parent[node];
    }

    bool unionSet(int u, int v) {
        int pu = find(u), pv = find(v);
        if (pu == pv) return false;
        if (rank[pv] > rank[pu]) swap(pu, pv);
        parent[pv] = pu;
        rank[pu] += rank[pv];
        return true;
    }
};

class Solution {
public:
    int shortestBridge(vector<vector<int>>& grid) {
        int N = grid.size();
        vector<vector<int>> direct = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        DSU dsu(N * N + 1);
        queue<pair<int, int>> q;

        auto idx = [&](int r, int c) {
            return r * N + c + 1;
        };

        int firstIsland = -1;
        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] == 1) {
                    firstIsland = dsu.find(idx(r, c));
                    if (c + 1 < N && grid[r][c + 1] == 1)
                        dsu.unionSet(idx(r, c), idx(r, c + 1));
                    if (r + 1 < N && grid[r + 1][c] == 1)
                        dsu.unionSet(idx(r, c), idx(r + 1, c));
                }
            }
        }

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] == 1 && dsu.find(idx(r, c)) == firstIsland) {
                    for (auto& d : direct) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nc >= 0 && nr < N && nc < N && grid[nr][nc] == 0) {
                            q.push({r, c});
                            break;
                        }
                    }
                }
            }
        }

        int res = 0;
        while (!q.empty()) {
            for (int i = q.size(); i > 0; i--) {
                auto [r, c] = q.front();q.pop();
                for (auto& d : direct) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nc >= 0 && nr < N && nc < N) {
                        if (grid[nr][nc] == 1 && dsu.unionSet(idx(r, c), idx(nr, nc)))
                            return res;
                        if (grid[nr][nc] == 0) {
                            grid[nr][nc] = 1;
                            dsu.unionSet(idx(r, c), idx(nr, nc));
                            q.push({nr, nc});
                        }
                    }
                }
            }
            res++;
        }
        return res;
    }
};

